"""Public experiment planning requests and results."""

from dataclasses import dataclass
from pathlib import Path
from typing import Literal

PlanStatus = Literal["blocked", "input_ready"]
type JSONValue = (
    None | bool | int | float | str | list[JSONValue] | dict[str, JSONValue]
)


@dataclass(frozen=True)
class ResolveRequest:
    """Select an experiment input relative to an explicit project root."""

    project_root: Path
    experiment: Path


@dataclass(frozen=True)
class Diagnostic:
    """Describe a blocking field or source problem without exposing content."""

    code: str
    field: str
    source_path: str
    line: int | None
    column: int | None
    message: str


@dataclass(frozen=True)
class PlanResult:
    """Report immutable capture identity and derived input readiness."""

    plan_id: str | None
    status: PlanStatus
    diagnostics: tuple[Diagnostic, ...]


class PlanningError(Exception):
    """Report an operational failure using a stable code and safe message."""

    def __init__(self, code: str, message: str) -> None:
        """Initialize the operational failure."""
        super().__init__(message)
        self.code = code


@dataclass(frozen=True)
class VerificationResult(PlanResult):
    """Report recomputed integrity and preserved-input readiness."""

    integrity: bool
    authentication: str = "none"
    approval_ids: tuple[str, ...] = ()


@dataclass(frozen=True)
class PlanInspection:
    """Expose preserved plan evidence with independently checked integrity."""

    plan_id: str
    status: PlanStatus
    integrity: bool
    plan: dict[str, JSONValue] | None
    diagnostics: tuple[Diagnostic, ...]
    authentication: str = "none"
    approval_ids: tuple[str, ...] = ()
"""Immutable, atomic local plan publication and evidence integrity checks."""

import hashlib
import json
import os
import re
import stat
import uuid
from pathlib import Path
from typing import cast

from agentic_ml.planning.models import JSONValue, PlanningError
from agentic_ml.planning.parsing import fail, mapping, sequence, strict_yaml
from agentic_ml.planning.paths import ProjectAccess

STORE = ".agentic-ml/plans"
SOURCE_NAMES = {
    "experiment.md",
    "search-space.yaml",
    "experiment.yaml",
    "project.yaml",
    "pyproject.toml",
    "uv.lock",
    "harness-origin.json",
}


def canonical(value: JSONValue) -> bytes:
    """Serialize finite JSON deterministically with one terminal newline."""
    return (
        json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        )
        + "\n"
    ).encode("utf-8")


def identifier(plan_id: str) -> str:
    """Validate a public immutable plan identifier."""
