def inspect_validation(*, project_root: Path, validation_id: str) -> ValidationInspection:
    """Independently rederive evidence integrity and current semantic inputs."""
    from agentic_ml.validation.storage import read_bundle

    access: ProjectAccess | None = None
    config: dict[str, JSONValue] | None = None
    intact = False
    try:
        access = ProjectAccess(project_root)
        config, registry, source = read_bundle(access, validation_id)
        intact = True
        selected = config["registry_source"]
        path = None if selected is None else str(mapping(selected)["path"])
        current, current_registry, current_source = derive(access, str(config["plan_id"]), path)
        if current != config or registry != current_registry or source != current_source:
            reject("stale_validation", "inputs", "Revalidate current inputs and library observations explicitly.")
        access.recheck()
        return ValidationInspection("valid", validation_id, config, (), True, True)
    except InputError as error:
        return ValidationInspection("blocked", validation_id, config, (error.diagnostic,), intact, False)
    except (FileNotFoundError, NotADirectoryError, ValueError, TypeError, KeyError) as error:
        diagnostic = Diagnostic("invalid_validation", "validation_id", "", None, None, "Restore intact evidence for this validation identity.")
        return ValidationInspection("blocked", validation_id, config, (diagnostic,), False, False)
    except PlanningError as error:
        raise ValidationError(error.code, str(error)) from error
    except OSError as error:
        raise ValidationError("validation_io", "Unable to access preserved validation evidence.") from error
    finally:
        if access is not None:
            access.close()
